  let cut = 0;
  if (edgeAtMs == null) {
    while (cut < buffer.length && nowMs - buffer[cut].tMs > cfg.preEdgeMs) cut += 1;
  } else {
    while (cut < buffer.length && edgeAtMs - buffer[cut].tMs > cfg.preEdgeMs) cut += 1;
