}

// ------------------------------------------------------------- self-test ----
if (has('self-test')) {
  const fails = [];
  const ok = (name, cond, extra = '') => { if (!cond) fails.push(`${name} ${extra}`); };
  const S = (o) => ({ story: { available: true, ...o } });

  // 1. atomic sampler structure: the installer is ONE function body, and every
